Input: {"question": "When was the Submarine Service established?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0330-0d7836f1a610:d00", "start": 0, "end": 161, "text": "Royal Australian Navy Submarine Service The Royal Australian Navy Submarine Service is the collective name of the submarine element of the Royal Australian Navy."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0330-0d7836f1a610:d00", "start": 162, "end": 284, "text": "The service currently forms the Navy's Submarine Force Element Group (FEG) and consists of six \"Collins\" class submarines."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0330-0d7836f1a610:d00", "start": 285, "end": 458, "text": "The Royal Australian Navy Submarine Service has been established four times, with the initial three attempts being foiled by combat losses and Australia's economic problems."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0330-0d7836f1a610:d00", "start": 459, "end": 603, "text": "The modern Submarine Service was established in 1964, and has formed an important element of the Australian military's capacity since that date."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0330-0d7836f1a610:d00", "start": 604, "end": 667, "text": "While the Submarine Service has not seen combat since World War"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 0, "end": 202, "text": "Royal Netherlands Navy Submarine Service The Royal Netherlands Navy Submarine Service (\"Onderzeedienst\") is a department of the Royal Netherlands Navy that is responsible for deploying Dutch submarines."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 203, "end": 315, "text": "It was set up on 21 December 1906, out of the Torpedo Service, and merged with the Mine Service on 15 July 2005."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 316, "end": 375, "text": "The submarine service was established on December 21, 1906."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 376, "end": 466, "text": "In this year the Royal Netherlands Navy commissioned its first submarine, the HNLMS \"O 1\"."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 467, "end": 582, "text": "The Submarine Service was tasked with taking care of the equipment of the submarines and the training of the crews."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0330-0d7836f1a610:d01", "start": 583, "end": 612, "text": "At this time there were still"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 0, "end": 73, "text": "prior to serving as an Executive Officer on board a Royal Navy submarine."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 74, "end": 168, "text": "It has been run twice a year since 1917, usually starting on 2 July and 14 November each year."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 169, "end": 282, "text": "It is widely regarded as one of the toughest command courses in the world, with a historical failure rate of 25%."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 283, "end": 434, "text": "If at any point during the training a candidate is withdrawn from training he will be nominated for boat transfer and kept occupied until the transfer."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 435, "end": 517, "text": "His bag is packed for him and he is notified of the failure when the boat arrives."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0330-0d7836f1a610:d02", "start": 518, "end": 536, "text": "On departure he is"}}, "original_cards": [{"doc_id": "ramdocs-0330-0d7836f1a610:d00", "card_id": "ramdocs-0330-0d7836f1a610:d00:c0", "entity": "modern Submarine Service", "scope": "Royal Australian Navy", "claim": "The modern Submarine Service was established in 1964.", "answer": "1964", "quote": "The modern Submarine Service was established in 1964, and has formed an important element of the Australian military's capacity since that date.", "original_document_number": 1}, {"doc_id": "ramdocs-0330-0d7836f1a610:d01", "card_id": "ramdocs-0330-0d7836f1a610:d01:c0", "entity": "Submarine Service", "scope": "Establishment date", "claim": "The Submarine Service was established on December 21, 1906.", "answer": "December 21, 1906", "quote": "It was set up on 21 December 1906, out of the Torpedo Service, and merged with the Mine Service on 15 July 2005. The submarine service was established on December 21, 1906.", "original_document_number": 2}], "current_answers": ["1964", "December 21, 1906"], "candidate_answers": [{"candidate_id": "R0", "answer": "1964", "origin": "initial"}, {"candidate_id": "R1", "answer": "December 21, 1906", "origin": "initial"}], "requested_slot_hint": "other"}
